cpp.solution:
#include <iomanip>
#include <iostream>
#include <sstream>
#include <string>

std::string toClock(int minutes) {
    int hours = minutes / 60;
    int mins = minutes % 60;
    std::ostringstream out;
    out << hours << ':' << std::setw(2) << std::setfill('0') << mins;
    return out.str();
}

int main() {
    int minutes;
    std::cin >> minutes;
    std::cout << toClock(minutes) << "\n";
    return 0;
}

